export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  const t = time;
  const tossedHeight = launchSpeed * t - (gravity * t * t) / 2;
  const tossedVelocity = launchSpeed - gravity * t;
  const tossedAcceleration = -gravity;

  const gateOpen = t >= apexTime;
  const dropTime = gateOpen ? (t - apexTime) : 0;
  const dropHeight = gateOpen ? (apexHeight - (gravity * dropTime * dropTime) / 2) : apexHeight;
  const dropVelocity = gateOpen ? (-gravity * dropTime) : 0;
  const dropAcceleration = gateOpen ? -gravity : 0;

  let tossState = "Rising";
  if (t <= 0.02) tossState = "At launch";
  else if (Math.abs(tossHeight - apexHeight) < 0.02) tossState = "At the top";
  else if (t > apexTime && tossedHeight > 0) tossState = "Falling";
  else if (tossedHeight <= 0) tossState = "At launch height";

  let dropState = "Held in place";
  if (gateOpen && dropTime < 0.02) dropState = "Just released";
  else if (gateOpen && dropHeight > 0) dropState = "Falling together";
  else if (dropHeight <= 0) dropState = "At launch height";

  const width = 640;
  const height = 420;

  const scaleY = 120;
  const originY = 320;

  function toScreenY(y) {
    return originY - y * scaleY;
  }

  const laneW = 280;
  const laneH = 260;
  const laneY = 100;

  const laneTossX = 30;
  const laneDropX = 330;

  const objects = [];

  objects.push(...sdk.panel({ x: laneTossX, y: laneY, w: laneW, h: laneH, title: "Toss lane", state: tossState, id: "lane.toss" }));
  objects.push(...sdk.panel({ x: laneDropX, y: laneY, w: laneW, h: laneH, title: "Drop lane", state: dropState, id: "lane.drop" }));

  objects.push(sdk.axis("axis.toss", { x: laneTossX + 40, y: laneY + laneH - 20, length: 200, orientation: "y", min: 0, max: 2.2, label: "Height", unit: "m" }));
  objects.push(sdk.axis("axis.drop", { x: laneDropX + 40, y: laneY + laneH - 20, length: 200, orientation: "y", min: 0, max: 2.2, label: "Height", unit: "m" }));

  const ballTossScreenX = laneTossX + 160;
  const ballDropScreenX = laneDropX + 160;

  const ballTossY = toScreenY(Math.max(0, Math.min(2.2, tossedHeight)));
  const ballDropY = toScreenY(Math.max(0, Math.min(2.2, dropHeight)));

  objects.push(sdk.circle("ball.toss", ballTossScreenX, ballTossY, 24, { role: "output" }));
  objects.push(sdk.circle("ball.drop", ballDropScreenX, ballDropY, 24, { role: "output" }));

  if (!gateOpen) {
    objects.push(sdk.gate("gate", ballDropScreenX, toScreenY(apexHeight), { open: false, label: "Gate" }));
  } else {
    objects.push(sdk.gate(	ext.gate", ballDropScreenX, toScreenY(apexHeight), { open: true, label: "Gate" }));
  }

  objects.push(...sdk.vector("vec.v.toss", { x: ballTossScreenX - 20, y: ballTossY }, { value: tossedVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: ballTossScreenX + 20, y: ballTossY }, { value: tossedAcceleration, direction: "up" }, { scale: 5, label: "a" }));

  objects.push(...sdk.vector("vec.v.drop", { x: ballDropScreenX - 20, y: ballDropY }, { value: dropVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: ballDropScreenX + 20, y: ballDropY }, { value: dropAcceleration, direction: "up" }, { scale: 5, label: "a" }));

  objects.push(...sdk.callout(ballTossScreenX + 40, ballTossY - 20, [
    "v: " + sdk.format(tossedVelocity) + " m/s",
    "a: " + sdk.format(tossedAcceleration) + " m/s²"
  ], { id: "callout.toss" }));

  objects.push(...sdk.callout(ballDropScreenX + 40, ballDropY - 20, [
    "v: " + sdk.format(dropVelocity) + " m/s",
    "a: " + sdk.format(dropAcceleration) + " m/s²"
  ], { id: "callout.drop" }));

  return {
    frame: {
      width,
      height,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
